<h3>Suivi</h3><dl class="detail-sheet__grid"><?=$sheetFact('DLC',date('d/m/Y',strtotime($s['expiry_date'])))?><?=$sheetFact('Saisi par',$s['author']?:'—',date('d/m/Y H:i',strtotime($s['created_at'])))?><?=$sheetFact('Validé par',$s['validator']?:'—',$s['validated_at']?date('d/m/Y H:i',strtotime($s['validated_at'])):'')?><?php if($s['status']==='validated'&&$s['weight_stock_id']): ?><?=$sheetFact('Stock à la ferme',$kg($s['stock_kg']).' kg',$s['available_pieces']>0?$int($s['available_pieces']).' carcasse(s), '.$kg($s['available_kg']).' kg à envoyer':'Entièrement envoyé')?><?php endif; ?></dl>
