elseif($s['status']==='validated'&&$s['available_pieces']>0&&$s['available_kg']>0&&$s['expiry_date']>=date('Y-m-d')&&Auth::can('livestock','create',$site)): ?><button type="button" class="btn-primary" data-workspace-modal-open="poultry-shipment" data-preselect-field="weight_stock_id" data-preselect-value="<?=e($s['weight_stock_id'])?>"><i class="bi bi-truck" aria-hidden="true"></i> Préparer un envoi</button><?php endif; ?>
</footer>
<?php require $flowViews.'/drawer_end.php'; ?>
