<h3>Double comptage et pesée</h3><dl class="detail-sheet__grid"><?=$sheetFact('Compté à la ferme',$int($sentPieces($t)).' '.$unit($t))?><?=$sheetFact('Pesé à la ferme',$kg($t['quantity_kg']).' kg',$live&&(float)$t['live_tare_kg']>0?'Brut '.$kg($t['live_gross_kg']).' − tare '.$kg($t['live_tare_kg']).($t['live_tare_note']?' ('.$t['live_tare_note'].')':''):'')?><?php if($gap!==null): ?><?=$sheetFact('Compté à la boucherie',$t['received_pieces']!==null?$int($t['received_pieces']).' '.$unit($t):'—',$t['received_pieces']!==null&&$sentPieces($t)>(int)$t['received_pieces']?$int($sentPieces($t)-(int)$t['received_pieces']).' manquant(s)':'')?><?=$sheetFact('Pesé à la boucherie',$kg($t['received_weight_kg']).' kg',(float)$t['received_tare_kg']>0?'Brut '.$kg($t['received_gross_kg']).' − tare '.$kg($t['received_tare_kg']).($t['receipt_tare_note']?' ('.$t['receipt_tare_note'].')':''):'Poids net')?><?=$sheetFact('Écart de poids',TransitWeighingService::describe($gap),$t['tolerance_pct']===null?'Aucune tolérance paramétrée':'Tolérance '.number_format((float)$t['tolerance_pct'],2,',',' ').' %')?><?php if($t['gap_reason']): ?><?=$sheetFact('Motif déclaré',$t['gap_reason'],$t['gap_approver']?'Écart validé par '.$t['gap_approver']:'')?><?php endif; ?><?php else: ?><?=$sheetFact('À la boucherie','—',$t['status']==='in_transit'?'En attente du comptage et de la pesée d’arrivée':'Non reçu')?><?php endif; ?></dl>
<h3>Suivi</h3><dl class="detail-sheet__grid"><?=$sheetFact('Préparé par',$t['author']?:'—',date('d/m/Y H:i',strtotime($t['created_at'])))?><?=$sheetFact('Approuvé par',$t['approver']?:'—')?><?=$sheetFact('Expédié par',$t['dispatcher']?:'—',$t['dispatched_at']?date('d/m/Y H:i',strtotime($t['dispatched_at'])):'')?><?=$sheetFact('Réception',$t['receipt_number']?:'—',$t['weigher']?'Pesé par '.$t['weigher'].($t['receipt_received_at']?' le '.date('d/m/Y H:i',strtotime($t['receipt_received_at'])):''):'')?></dl>
</div>
<footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button><button type="button" class="btn-secondary" data-workspace-modal-open="btr-preview" data-btr-url="<?=e(base_url('livestock/poultry/shipments/'.$t['id'].'/btr'))?>" data-btr-title="<?=e($t['transfer_number'])?>" data-workspace-return-focus="poultry-shipment-menu-<?=e($t['id'])?>-toggle"><i class="bi bi-file-earmark-text" aria-hidden="true"></i> Bon de transfert</button>
<?php if($t['status']==='draft'&&Auth::can('livestock','validate',$site)):$rowAction='livestock/poultry/shipments/'.$t['id'].'/approve';$rowConfirm='Approuver cet envoi ?';$rowLabel='Approuver';$rowIcon='bi-check2-circle';require dirname(__DIR__).'/partials/row_form.php';
elseif($t['status']==='approved'&&Auth::can('livestock','update',$site)):$rowAction='livestock/poultry/shipments/'.$t['id'].'/dispatch';$rowConfirm=$live?'Confirmer le départ des poulets vivants ? Ils quittent l’effectif du lot.':'Confirmer le départ des carcasses vers la boucherie ?';$rowLabel='Expédier';$rowIcon='bi-truck';require dirname(__DIR__).'/partials/row_form.php';endif; ?>
</footer>
<?php require $flowViews.'/drawer_end.php'; ?>
